def solve(inputs: dict) -> float:
    # Compute numerator of a finite continued fraction from its terms.
    # Expected input: terms = [a0, a1, ..., an]
    terms = inputs.get('terms') or inputs.get('a') or inputs.get('coeffs')
    if terms is None:
        raise ValueError('Expected continued fraction terms in inputs')
    p_minus2, p_minus1 = 0, 1  # standard numerator recurrence initialization
    # To match the prompt's convention p(-1)=1, p0=a0, we can use direct recurrence:
    # p_i = a_i * p_{i-1} + p_{i-2}, with p_{-1}=1, p_0=a_0.
    if not terms:
        return 0.0
    p_im2 = 1
    p_im1 = terms[0]
    if len(terms) == 1:
        return float(p_im1)
    for a in terms[1:]:
        p = a * p_im1 + p_im2
        p_im2, p_im1 = p_im1, p
    return float(p_im1)

